"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Signal in the Static', 'author': 'Signature original', 'genre': 'Cyber Cities', 'chapters': [{'n': 1, 'title': 'Contraband', 'text': "the ex-enforcer Cole took one look and went pale. 'This is pre-Collapse,' the ex-enforcer Cole whispered. 'the Overseer killed people for less than this. We have to move. Now.'\n\nNyx Carter watched the footage with tears they didn't authorize: green things growing, people laughing unmonitored, a sky without drones. 'memory is resistance,' Nyx Carter breathed. 'We have to show them.'\n\nIn the safehouse, the ex-enforcer Cole cracked it open — carefully, lovingly, the way you defuse a bomb. What spilled out wasn't data. It was memory. Real memory. Of the Sprawl before."}, {'n': 2, 'title': 'The Network', 'text': "'They're going to come for us,' the ex-enforcer Cole said. Nyx Carter nodded. 'Let them. We're already everywhere.'\n\na paper book was copied, hand to hand, each copy a little degraded, each copy a little more precious. Nyx Carter watched a twelve-year-old memorize the whole thing rather than risk carrying it. The future, Nyx Carter thought, is in good hands.\n\nThe Overseer's broadcast that night was the usual: safety, order, gratitude. Nyx Carter watched it on a cracked screen and saw, for the first time, the fear underneath. the Overseer was scared of a paper book. Of memory. Of truth."}, {'n': 3, 'title': 'Blackout', 'text': "At the top, the ex-enforcer Cole's hands flew. 'Thirty seconds to signal,' the ex-enforcer Cole said. Below, the Patrol's lights converged like angry stars. Nyx Carter stood at the window with a paper book and thought of green things growing.\n\nThe tower's guards were human, which meant they could be convinced. Nyx Carter showed them a paper book — thirty seconds of the before — and watched their faces change. They stood aside. Some revolutions are just remembering, together.\n\n'Now,' said the ex-enforcer Cole. And the Sprawl — all of the Sprawl, every screen, every speaker — remembered."}, {'n': 4, 'title': 'The Remembering', 'text': "the Overseer responded the only way the Overseer knew: force. The Patrol marched. The drones rose. And the people of the Sprawl — who had just remembered green, and laughter, and sky — stood in the streets and would not move.\n\nNyx Carter and the ex-enforcer Cole were in the tower when the door blew. The ex-enforcer held the stairs long enough. Long enough for what? For the footage to loop. For the memory to root. For the Overseer's lie to die on every screen at once.\n\na paper book burned out in the broadcast — one use, that was the price. Nyx Carter held the dead chip and didn't mourn it. Seeds die to grow. That was the whole point."}, {'n': 5, 'title': 'After the Static', 'text': "And when the new council asked Nyx Carter to lead, Nyx Carter laughed and went back to the food lines. Leaders, Nyx Carter had learned, are just people who show up. Nyx Carter shows up.\n\nThere were trials. the Overseer's people faced justice — real justice, not the Algorithm's kind, with evidence and mercy both. Some were guilty. Some were just afraid. Nyx Carter learned the difference matters.\n\nNyx Carter kept the dead chip in a pocket. A reminder: that truth is a seed, that seeds die to grow, that one a paper book in the right hands at the right time is worth an army."}, {'n': 6, 'title': 'The Habit of Freedom', 'text': "Years later, the Sprawl has gardens on the roofs and children who've never seen a drone. They learn the story of a paper book in school, and Nyx Carter always winces at the statue. 'I just carried it,' Nyx Carter protests. Nobody believes that anymore.\n\nAnd somewhere, in a gutter where drones don't look, someone is finding something warm that shouldn't be warm. It starts again. It always starts again. That's the best part.\n\nmemory is resistance — Nyx Carter thinks it every time, like a prayer, like a promise. Memory is resistance. Freedom is a habit. Practice daily."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

